#include "turtle_control_structure_cpp_pkg/base_headers/proc_pilot_base_src.hpp"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

proc_pilot_base::proc_pilot_base() : Node("proc_pilot")
{
    cb_group_ = this->create_callback_group(rclcpp::CallbackGroupType::Reentrant);
    subscription_options_.callback_group = cb_group_;

    // Setting up connections
    proc_pilot_speed_subscription_ = this->create_subscription<turtle_control_structure_cpp_pkg_interfaces::msg::WheelSpeed>(
        "proc_pilot_speed",
        1,
        std::bind(&proc_pilot_base::handle_speed, this, std::placeholders::_1), subscription_options_);

    proc_pilot_overspeed_subscription_ = this->create_subscription<turtle_control_structure_cpp_pkg_interfaces::msg::Empty>(
        "proc_pilot_overspeed",
        1,
        std::bind(&proc_pilot_base::event_handle_overspeed, this, std::placeholders::_1), subscription_options_);

    proc_pilot_pose_subscription_ = this->create_subscription<turtlesim::msg::Pose>(
        "proc_pilot_pose",
        1,
        std::bind(&proc_pilot_base::handle_pose, this, std::placeholders::_1), subscription_options_);

    proc_pilot_cmdVel_publisher_ = this->create_publisher<geometry_msgs::msg::Twist>(
        "proc_pilot_cmdVel",
        1);

    proc_pilot_mode_publisher_ = this->create_publisher<turtle_control_structure_cpp_pkg_interfaces::msg::OperatingMode>(
        "proc_encoder_mode",
        1);

    proc_pilot_calibrate_publisher_ = this->create_publisher<turtle_control_structure_cpp_pkg_interfaces::msg::Empty>(
        "proc_encoder_calibrate",
        1);

    proc_pilot_trim_publisher_ = this->create_publisher<turtle_control_structure_cpp_pkg_interfaces::msg::TrimCommand>(
        "proc_encoder_trim",
        1);

}

void proc_pilot_base::init_pose(turtlesim::msg::Pose val) {
    pose_msg_holder = std::make_shared<turtlesim::msg::Pose>(val);
}

//=================================================
//  C o m m u n i c a t i o n
//=================================================

void proc_pilot_base::handle_pose(const turtlesim::msg::Pose::SharedPtr msg)
{
    pose_msg_holder = msg;
}

turtlesim::msg::Pose::SharedPtr proc_pilot_base::get_pose() {
    return pose_msg_holder;
}

void proc_pilot_base::event_handle_overspeed(const turtle_control_structure_cpp_pkg_interfaces::msg::Empty::SharedPtr msg)
{
    (void)msg;
    handle_overspeed();
}

void proc_pilot_base::put_cmdVel(geometry_msgs::msg::Twist msg)
{
    proc_pilot_cmdVel_publisher_->publish(msg);
}

void proc_pilot_base::put_mode(turtle_control_structure_cpp_pkg_interfaces::msg::OperatingMode msg)
{
    proc_pilot_mode_publisher_->publish(msg);
}

void proc_pilot_base::put_calibrate()
{
    turtle_control_structure_cpp_pkg_interfaces::msg::Empty msg = turtle_control_structure_cpp_pkg_interfaces::msg::Empty();

    proc_pilot_calibrate_publisher_->publish(msg);
}

void proc_pilot_base::put_trim(turtle_control_structure_cpp_pkg_interfaces::msg::TrimCommand msg)
{
    proc_pilot_trim_publisher_->publish(msg);
}

